import {image,caption,icon} from './shared.js';
export function renderScreen(m,header=''){if(m.layout==='split')return m.panels.map(p=>`<div class="panel">${image(p.image,p.title,true)}${caption(p)}</div>`).join('');return image(m.image,m.title,m.layout==='hero')+header+caption(m)}
export function renderGrid(m){return `<div class="grid">${m.items.map(p=>`<a class="card" href="#${m.layout==='categories'?'edit':'collection'}"><div class="card-image">${image(p.image,p.title)}</div><div class="card-label"><h2>${p.title}</h2>${m.layout!=='categories'?'<span class="text-link">DISCOVER</span>':''}</div></a>`).join('')}</div>${m.layout==='products'?'<a class="view-more text-link" href="#collection">VIEW MORE</a>':''}`}
export function renderServices(){return Array.from({length:3},()=>`<div class="service"><span class="service-icon">${icon('shipping','')}</span><div class="service-copy"><h3>Free Returns</h3><p>All full-priced orders can be returned or exchanged within 14 days</p></div><span class="service-chevron">${icon('chevron','')}</span></div>`).join('')}
